"""Generate the typed RV32 public helper API from the reviewed local ABI JSON."""
import argparse
import json
import pathlib

ROOT = pathlib.Path(__file__).resolve().parents[2]
HEADER = ROOT / 'verification/sw/common/xpulpnn.h'


def render():
    manifest = json.loads((ROOT / 'verification/manifests/xpulpnn_isa.json').read_text())
    forms = manifest['forms']
    if len(forms) != 72 or len({form['name'] for form in forms}) != 72:
        raise ValueError('Reviewed ABI must contain exactly 72 distinct forms')
    lines = [
        '/* Generated by verification/scripts/generate_xpulpnn_helpers.py; do not edit.',
        ' * FYP DATE2020-local-v1, custom local machine codes, RV32 only.',
        ' * avg wraps each lane BEFORE arithmetic right shift; avgu uses logical shift.',
        ' * Examples: avg.n(7,7)=-1; avgu.n(15,15)=7. No rounding increment.',
        ' * dotusp/sdotusp: unsigned A (rs1), signed B (rs2).',
        ' * sc broadcasts only B low4/low2 bits; sdot reads and updates old rd.',
        ' * qnt: signed16 activations, sign-extended signed16 thresholds in int32 words,',
        ' * 64-byte channel stride. Tables must satisfy the documented base/layout ABI.',
        ' */',
        '#ifndef FYP_XPULPNN_H', '#define FYP_XPULPNN_H', '#include <stdint.h>',
        '#if defined(__riscv_xlen) && __riscv_xlen != 32',
        '#error "The FYP XpulpNN helper ABI requires RV32"', '#endif',
        '#define XPULPNN_ABI_VERSION 1', '#define XPULPNN_TABLE_CHANNEL_BYTES 64', '',
    ]
    for form in forms:
        name = 'xpulpnn_' + form['name'].replace('.', '_')
        op = form['op']
        fmt = f'.insn r 0x7b, {form["funct3"]}, {form["funct6"] << 1}'
        if op == 'abs':
            lines += [f'static inline uint32_t {name}(uint32_t a) {{',
                      '  uint32_t result;',
                      f'  __asm__("{fmt}, %0, %1, x0" : "=r"(result) : "r"(a));']
        elif op == 'qnt':
            lines += [f'static inline uint32_t {name}(uint32_t packed_act16, const int32_t *tables) {{',
                      '  uint32_t result;', '  uint32_t base = (uint32_t)(uintptr_t)tables;',
                      f'  __asm__ volatile("{fmt}, %0, %1, %2"',
                      '                   : "=r"(result) : "r"(packed_act16), "r"(base) : "memory");']
        elif op.startswith('sdot'):
            lines += [f'static inline uint32_t {name}(uint32_t acc, uint32_t a, uint32_t b) {{',
                      '  uint32_t result = acc;',
                      f'  __asm__("{fmt}, %0, %1, %2" : "+r"(result) : "r"(a), "r"(b));']
        else:
            lines += [f'static inline uint32_t {name}(uint32_t a, uint32_t b) {{',
                      '  uint32_t result;',
                      f'  __asm__("{fmt}, %0, %1, %2" : "=r"(result) : "r"(a), "r"(b));']
        lines += ['  return result;', '}', '']
    lines += ['#endif', '']
    return '\n'.join(lines)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    text = render()
    if args.check:
        if not HEADER.exists() or HEADER.read_text() != text:
            raise SystemExit('Generated xpulpnn.h is missing or stale')
        print('Typed public helper API matches the 72-form ABI')
    else:
        HEADER.parent.mkdir(parents=True, exist_ok=True)
        HEADER.write_text(text)
        print(f'Generated {HEADER}')


if __name__ == '__main__':
    main()
